import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>在照片里藏住一张脸或一个地址，只需要几分钟。画笔涂过敏感部位，检查结果，下载遮盖后的副本就行。</p>\n<p>这篇教程会带你走完整个流程。包括画笔模式与整图模式、模糊与打码、画笔大小，以及确认没有任何东西还可读的检查步骤。</p>\n<p>读完之后，人脸、车牌、截图或文件，你都能在任何设备上干净地遮盖。下载之前先检查，确认无误再分享；没有遮盖的原文件单独存放。</p>\n<h2 id=\"before-you-start\">开始之前：列出需要隐藏的东西</h2>\n<p>打开原照片，列出里面所有敏感内容：人脸、地址、车牌、屏幕、文件、胸牌上的名字。背景和前景都要检查。</p>\n<p>倒影也要找。脸可能出现在镜子、窗户或太阳镜里，每一处都要遮盖，不只是主要的那一处。</p>\n<p>开始前决定用模糊还是打码。文字和数字用打码更安全，人脸和背景用重度模糊效果很好。</p>\n<p>打开<a href=\"/zh/mohu-masaike/\">模糊与马赛克图片工具</a>。所有处理都在本地完成，照片不会上传到服务器。</p>\n<h2 id=\"step-by-step\">6步模糊或打码一张图片</h2>\n<p>人脸、车牌、截图，流程都一样：上传、选模式、涂抹或应用、检查、下载。</p>\n<p>涂抹这一步值得花时间。现在认真涂一笔，比图片分享出去后才发现细节还可读要好得多。</p>\n<ol>\n<li>把图片拖进上传区，或者从设备里选择，也可以按Ctrl+V粘贴截图。</li>\n<li>选画笔区域模式涂抹特定细节，或选整图模式模糊整张照片。</li>\n<li>选平滑模糊或打码马赛克，设置画笔大小和强度或方块大小。</li>\n<li>用画笔涂过每个敏感区域，人脸全盖住，文字涂得慷慨一点。</li>\n<li>放大预览结果，确认没有任何东西还可读或可认。</li>\n<li>选择导出格式和画质，点“下载”保存遮盖后的图片。</li>\n</ol>\n<p>分享之前先打开下载好的文件看一次。按全尺寸检查，确认每个敏感细节都藏住了。</p>\n<h2 id=\"choosing-blur-or-pixelate\">模糊还是打码，怎么选</h2>\n<p>人脸和背景选平滑模糊。重度模糊去掉面部特征，照片看起来依然自然，很适合人像。</p>\n<p>文字、数字和地址选打码马赛克。马赛克方块彻底破坏字母形状，轻柔的模糊有时还会留下轮廓可读。</p>\n<p>同一张图片里可以混用两种方法。脸涂模糊，车牌涂打码，涂抹之间切换模式就行。</p>\n<p>拿不准就用打码。马赛克稍强一点看着是故意的，模糊稍弱一点却会让细节依然可读。</p>\n<h2 id=\"using-brush-mode\">使用画笔区域模式</h2>\n<p>画笔区域模式是最精确的选择。效果只涂在你需要的地方，图片其余部分保持清晰、不受影响。</p>\n<p>先用大画笔涂主要区域，比如整张脸。盖住整个头部，包括发际线、耳朵和下巴，不只是眼睛。</p>\n<p>再换小画笔处理边缘。小画笔可以沿着单个词描，或者清理遮盖区域的边界，不碰其余部分。</p>\n<p>撤销按钮去掉最后一笔，重置按钮清除所有画笔涂抹。放心用它们；重涂一笔比分享一张遮盖不当的照片快得多。</p>\n<h2 id=\"using-whole-image-mode\">使用整图模式</h2>\n<p>整图模式把效果一次性应用到整张照片。整张图片都敏感，或者想要一个模糊背景做设计时，就用它。</p>\n<p>把目标区域切换到整图，工具会把当前的模糊或打码强度应用到整个画面。颜色和氛围还在，没有任何细节能留下来。</p>\n<p>完全模糊的照片很适合做文字或演示文稿的背景。图片加了色彩，又不分散观众对上面文字的注意力。</p>\n<p>不要用整图模式处理想让人看清楚的照片。整张模糊的照片连主体一起藏住了，公开分享时很少是正确的选择。</p>\n<h2 id=\"setting-brush-size\">设置画笔大小</h2>\n<p>画笔大小要和你要隐藏的细节匹配。脸需要大画笔，车牌需要中等画笔，单个词需要小画笔。</p>\n<p>画笔太大，遮住的比想遮的多。可能盖住旁边的一张脸，或者图片里本来不需要隐藏的有用部分。</p>\n<p>画笔太小，盖住大面积要涂很多笔，笔触之间的缝隙可能漏出敏感细节的一小条。</p>\n<p>边涂边调整大小。先用大画笔涂主要区域，再换小画笔清理边缘、补上漏掉的地方。</p>\n<h2 id=\"setting-strength\">设置模糊强度与方块大小</h2>\n<p>模糊强度和马赛克方块大小都决定了还剩下多少信息。数值越高，藏得越多；数值越低，藏得越少。</p>\n<p>人脸用重度模糊或大方块。眼睛和微笑还看得见的轻度模糊保护不了任何人，小方块也还留着脸的形状。</p>\n<p>小截图用中等方块就够了。文字很小，就算是适度的马赛克也能彻底破坏字母形状。</p>\n<p>放大测试结果。按全尺寸看，文字还能读、脸还能认，就调高强度再检查一次。</p>\n<h2 id=\"fixing-mistakes\">涂抹时出了错怎么办</h2>\n<p>一笔涂错了，用撤销按钮去掉它。撤销是按笔触一步步回退的，可以一次退一步，不会丢掉已经做好的工作。</p>\n<p>整个遮盖看起来都不对，用重置按钮清除所有画笔涂抹。重新开始比费劲修补一堆乱涂抹更快。</p>\n<p>留意笔触之间的缝隙。两笔之间漏出的一小条可见文字，可能暴露被藏的词，所以涂抹时稍微重叠一点。</p>\n<p>检查每个遮盖区域的边缘。露出耳朵的脸、露出一位数字的车牌，就算中间盖住了，也算没有藏好。</p>\n<h2 id=\"preview-and-compare\">下载前预览</h2>\n<p>下载之前一定要预览。每个遮盖区域都按全尺寸放大，确认没有任何特征、字母或数字还可读。</p>\n<p>背景和前景都要检查。窗户或镜子里的倒影，可能正好露出你刚在主画面里遮住的脸或地址。</p>\n<p>有条件的话在大屏幕上看。手机上看着藏住的细节，电脑显示器上放大了可能又可读了。</p>\n<p>还有东西可读就调高强度或再补一笔。现在修好，比召回已经分享出去的图片容易得多。</p>\n<h2 id=\"choosing-export-format\">选择导出格式</h2>\n<p>要分享的照片选JPG。文件小，哪里都能打开，遮盖区域压缩后也很干净。</p>\n<p>截图和带文字的图片选PNG。PNG是无损的，没有遮盖的部分边缘保持锐利，还能保留透明度。</p>\n<p>想要小文件又要好画质时选WebP。很适合网页图片，不过少数老系统还不支持这个格式。</p>\n<p>注意，PNG没有画质滑杆，因为PNG是无损的，没有画质可调。这很正常，不是工具出问题。</p>\n<h2 id=\"blurring-on-mobile\">在手机或平板上打码</h2>\n<p>工具支持触屏，可以直接在拍照的那部手机上给照片打码。从相册上传，手指涂抹敏感区域。</p>\n<p>小屏幕上用大一点的画笔。手指涂抹不如鼠标精确，大画笔不用涂很多笔就能可靠地盖住区域。</p>\n<p>涂小细节之前先放大。车牌或单个词需要凑近了看，放大后就算在手机上涂抹也能很准确。</p>\n<p>下载的文件会进到你常用的下载文件夹。之后可以直接把遮盖后的图片分享到聊天软件、邮件或社交平台。</p>\n<h2 id=\"blurring-screenshots\">给截图打码</h2>\n<p>截图直接按Ctrl+V粘贴，跳过保存步骤。图片会立刻出现在工具里，可以马上遮盖。</p>\n<p>涂掉姓名、邮箱地址、密码和内部网址。仪表盘截图常常比你想分享的部分暴露得更多。</p>\n<p>截图里的文字用打码。马赛克彻底破坏字母形状，轻柔的模糊在全尺寸下可能还留下一部分可读性。</p>\n<p>截图导出选PNG。无损格式让没有遮盖的文字保持锐利，截图要展示设置或报错信息时，这一点很重要。</p>\n<h2 id=\"blurring-documents\">给文件照片打码</h2>\n<p>文件照片里常常有好几处姓名、地址和身份证号。开始涂抹之前全列出来，一处都不能漏。</p>\n<p>整行文字都盖住，不只是敏感的那个词。行的长度和周围的词可能暴露被藏的部分。</p>\n<p>检查文件照片的边缘。第二页、倒影或阴影里，可能藏着同样的信息，出现在你没想到的地方。</p>\n<p>必须分享的文件，考虑把敏感部分直接裁掉。裁剪是永久去掉数据，模糊只是在这一个文件里把它藏起来。</p>\n<h2 id=\"troubleshooting\">常见打码问题排查</h2>\n<p>脸还是可认，模糊太轻或方块太小。调高强度，重新涂抹，直到看不见任何特征。</p>\n<p>文字还是可读，从模糊换成打码。大方块的马赛克破坏字母形状的可靠性，远胜轻柔的模糊。</p>\n<p>撤销和重置按钮不见了，检查是不是在整图模式。撤销和重置按钮只在画笔区域模式出现，因为那里才有可撤销的笔触。</p>\n<p>预览和下载看起来不一样，检查导出格式和画质。JPG画质设置太低会让整张图片变软，包括你想保持清晰的部分。</p>\n<h2 id=\"quick-tips\">更安全的打码小技巧</h2>\n<p>遮盖要慷慨。多盖一点没有坏处，漏出一小条脸或一位数字却会让整个遮盖白费。</p>\n<p>每涂一笔都放大检查。快速放大能及时发现缝隙和漏掉的地方，不会变成分享出去的错误。</p>\n<p>只分享遮盖后的文件。原文件放在单独的文件夹里，永远不要和遮盖版本附在同一条消息或帖子里。</p>\n<p>导出后检查元数据。工具会清除GPS标签，但公开分享之前，确认下载的文件不带位置记录。</p>\n<h2 id=\"blurring-for-presentations\">演示文稿里的模糊背景</h2>\n<p>模糊的照片是干净的幻灯片背景。柔和的色彩增加了视觉趣味，顶上的文字从教室后排也能看清。</p>\n<p>用整图模式加适度模糊，再把标题和要点放在上面。模糊要够强，文字才可读；又要够轻，照片还看得出来。</p>\n<p>幻灯片文字要大、对比度要高。深色模糊照片上的白色文字效果很好，深色文字则需要浅色模糊背景才可读。</p>\n<p>背景导出用高画质JPG。干净的背景让整张幻灯片看着专业，低画质导出会连文字一起变软。</p>\n<p>对比分析读<a href=\"/zh/blog/mohu-vs-masaike-duibi/\">模糊 vs 马赛克：隐藏人脸、文字与细节</a>。完整概览见<a href=\"/zh/blog/tupian-mohu-masaike-wanquan-zhinan/\">图片模糊与马赛克完全指南</a>；想彻底删除位置数据，用<a href=\"/zh/shanchu-tupian-yuanshuju/\">删除图片元数据工具</a>。</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"合影里只模糊一张脸怎么做？","answer":"用画笔区域模式，只涂那一张脸，大画笔加高强度模糊或马赛克。照片其余部分保持清晰。之后放大确认整个头部都盖住了，包括发际线和耳朵。"},{"question":"同一张图片里能同时用模糊和打码吗？","answer":"能。脸涂平滑模糊，文字或车牌涂打码马赛克，涂抹之间切换模式就行。两种效果可以在一张图片上混用。"},{"question":"车牌用多大的画笔？","answer":"中等画笔，两三笔能盖住车牌的大小就好。用打码加中等到大方块，因为文字需要马赛克破坏字母形状。放大确认没有任何数字还可读。"},{"question":"手机上怎么给截图打码？","answer":"在手机浏览器里打开工具，从相册上传截图，选画笔区域模式。手指涂抹姓名和密码，文字用大画笔加打码，下载遮盖后的副本。"},{"question":"为什么撤销和重置按钮不见了？","answer":"它们只在画笔区域模式出现，因为那里才有可撤销的笔触。整图模式下没有画笔涂抹，按钮会隐藏。切换回画笔区域模式就能涂抹，也能用撤销和重置。"},{"question":"在网上分享模糊过的孩子照片安全吗？","answer":"重度模糊或打码的人脸，比看得见的脸安全得多，但没有任何方法绝对完美。用大方块马赛克或重度模糊，盖住整个头部，按全尺寸检查结果。原文件不要在任何地方分享。"}];
